import{_ as t,o,c as n,a2 as a}from"./chunks/framework.CZo9GF0W.js";const u=JSON.parse('{"title":"07 — Task Breakdown","description":"","frontmatter":{},"headers":[],"relativePath":"07-TASKS.md","filePath":"07-TASKS.md","lastUpdated":1789060268000}'),s={name:"07-TASKS.md"};function r(i,e,d,c,l,h){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="_07-—-task-breakdown" tabindex="-1">07 — Task Breakdown <a class="header-anchor" href="#_07-—-task-breakdown" aria-label="Permalink to &quot;07 — Task Breakdown&quot;">​</a></h1><p>Format: <code>P&lt;phase&gt;-T&lt;n&gt;</code> · size <strong>S</strong> ≤ 1 d · <strong>M</strong> 2–3 d · <strong>L</strong> 4–5 d. Deps in brackets.</p><h2 id="phase-0-—-foundations" tabindex="-1">Phase 0 — Foundations <a class="header-anchor" href="#phase-0-—-foundations" aria-label="Permalink to &quot;Phase 0 — Foundations&quot;">​</a></h2><ul><li>[x] <strong>P0-T1</strong> (M) pnpm workspace + TS strict + package skeletons (<code>core</code>, <code>driver-pg</code>, <code>protocol</code>, <code>extension</code>, <code>webview-ui</code>)</li><li>[x] <strong>P0-T2</strong> (M) esbuild extension bundle · Vite webview build · watch tasks · <code>.vscode/launch.json</code></li><li>[x] <strong>P0-T3</strong> (S) <code>package.json</code> contributes stub: activation events, one command, view container, icon placeholder</li><li>[x] <strong>P0-T4</strong> (S) eslint + <code>dependency-cruiser</code> boundary rules (<code>core</code> ⊬ <code>vscode</code>/<code>pg</code>; <code>webview-ui</code> ⊬ <code>extension</code>)</li><li>[x] <strong>P0-T5</strong> (S) Vitest config + first unit test; <code>@vscode/test-electron</code> harness stub</li><li>[x] <strong>P0-T6</strong> (M) GitHub Actions: lint · typecheck · unit · VSIX artifact upload</li><li>[x] <strong>P0-T7</strong> (S) <code>docker-compose.test.yml</code> — PG 13/15/17 + seeded fixture schema</li><li>[x] <strong>P0-T8</strong> (S) Logger + output channel + secret redaction pass [S1.4]</li></ul><h2 id="phase-1-—-connections-explorer" tabindex="-1">Phase 1 — Connections + Explorer <a class="header-anchor" href="#phase-1-—-connections-explorer" aria-label="Permalink to &quot;Phase 1 — Connections + Explorer&quot;">​</a></h2><ul><li>[x] <strong>P1-T1</strong> (L) <code>DriverAdapter</code> / <code>Session</code> / <code>QueryHandle</code> / <code>DriverCapabilities</code> types + <code>defineDriver</code> registry [P0-T1]</li><li>[x] <strong>P1-T2</strong> (L) <code>driver-pg</code> connect: node-postgres pool, TLS modes, server-version probe, <code>application_name</code>, <code>search_path</code>, <code>TimeZone</code></li><li>[x] <strong>P1-T3</strong> (M) Out-of-band CancelRequest implementation + test against <code>pg_stat_activity</code></li><li>[x] <strong>P1-T4</strong> (M) SSH tunnel via <code>ssh2</code>: password / key+passphrase / agent, jump host, <code>known_hosts</code> verification [S2.3]</li><li>[x] <strong>P1-T5</strong> (M) SecretStorage service + <code>SecretRef</code> resolvers: keychain, env, <code>.pgpass</code>, <code>pg_service.conf</code>, prompt</li><li>[x] <strong>P1-T6</strong> (M) <code>ConnectionProfile</code> model + global store + workspace file store + JSON Schema (rejects secret literals) [S1.2]</li><li>[x] <strong>P1-T7</strong> (L) Connection form webview, rendered from <code>connectionSchema</code>; Test Connection; URI paste parser</li><li>[x] <strong>P1-T8</strong> (S) Environment tag + color + read-only flag; status-bar and tree decoration</li><li>[x] <strong>P1-T9</strong> (M) <code>protocol</code> package: zod-validated RPC envelope + typed client/host helpers [S5.2]</li><li>[x] <strong>P1-T10</strong> (L) <code>IntrospectionPlan</code> for PG: databases, schemas, tables, views, matviews, foreign tables, functions, types, sequences, extensions — version-gated 13→17</li><li>[x] <strong>P1-T11</strong> (L) TreeDataProvider: lazy children, filter box, refresh, context menu, drag-reorder groups</li><li>[x] <strong>P1-T12</strong> (M) Metadata cache: TTL, eager DDL invalidation, disk persistence</li><li>[x] <strong>P1-T13</strong> (M) Integration tests vs docker PG 13/15/17 in CI</li><li>[x] <strong>P1-T14</strong> (S) Security test: grep entire storage dir for any credential after a full connect flow [S1.1]</li></ul><h2 id="phase-2-—-query-mode-mvp-→-m1" tabindex="-1">Phase 2 — Query mode MVP → <strong>M1</strong> <a class="header-anchor" href="#phase-2-—-query-mode-mvp-→-m1" aria-label="Permalink to &quot;Phase 2 — Query mode MVP  → **M1**&quot;">​</a></h2><blockquote><p><strong>Complete.</strong> The grid, wire encoding, and panel shell are shared components - query results mount the same <code>Grid</code> as the data view. P2-T12 is covered by the integration suite rather than <code>@vscode/test-electron</code>; a real E2E harness is still outstanding.</p></blockquote><ul><li>[x] <strong>P2-T1</strong> (M) Editor↔connection binding: status bar picker, per-file persistence, <code>-- @pitta connection:</code> directive</li><li>[x] <strong>P2-T2</strong> (M) Statement splitter: dollar-quoting, <code>E&#39;&#39;</code>, nested comments, <code>\\</code> meta-command subset</li><li>[x] <strong>P2-T3</strong> (S) CodeLens <code>▶ Run · Explain · Explain Analyze</code> + keybindings + cancel command</li><li>[x] <strong>P2-T4</strong> (L) Execution engine: multi-statement queue, per-statement result, timing, <code>commandTag</code>, abort wiring</li><li>[x] <strong>P2-T5</strong> (L) Results webview shell: tabbed panels, state restore across reload, theme tokens</li><li>[x] <strong>P2-T6</strong> (L) <strong>Grid v1</strong>: TanStack Virtual rows+cols, columnar store, type renderers, <code>NULL</code> token, exact <code>numeric</code> [04 §4]</li><li>[x] <strong>P2-T7</strong> (M) Type handler table for PG: arrays, json/jsonb, ranges, enums, domains, composites, uuid, bytea, interval, timestamptz, bigint, numeric</li><li>[x] <strong>P2-T8</strong> (S) Messages tab — live <code>NOTICE</code>/<code>WARNING</code>/<code>RAISE</code> streaming</li><li>[x] <strong>P2-T9</strong> (M) Statement analyzer v1 (heuristic) + guards: destructive confirm, unqualified-DML block, read-only enforcement [S4]</li><li>[x] <strong>P2-T10</strong> (S) Error surfacing: <code>SQLSTATE</code>, message, hint, character position → editor squiggle</li><li>[x] <strong>P2-T11</strong> (S) Copy-as TSV / CSV / JSON / Markdown / <code>INSERT</code></li><li>[x] <strong>P2-T12</strong> (M) E2E test: open file, bind connection, run, assert grid contents</li></ul><h2 id="phase-3-—-ui-mode-data-view-editing" tabindex="-1">Phase 3 — UI mode: data view &amp; editing <a class="header-anchor" href="#phase-3-—-ui-mode-data-view-editing" aria-label="Permalink to &quot;Phase 3 — UI mode: data view &amp; editing&quot;">​</a></h2><blockquote><p>Remaining in this phase: <strong>P3-T9</strong> (Structure panel tabs). DDL generation (P3-T10) ships as a read-only virtual <code>sql</code> document rather than a webview tab, so it gets syntax highlighting, find, and Save As for free. Paging is still offset-based; keyset is implemented and tested in <code>buildSelect</code> but not yet wired into the data view.</p></blockquote><ul><li>[x] <strong>P3-T1</strong> (L) <code>buildSelect</code>: filters + sorts + keyset paging, <code>LIMIT/OFFSET</code> fallback, params only [S3.1]</li><li>[x] <strong>P3-T2</strong> (L) Table Data panel: grid reuse, generated-SQL bar, page controls, refresh</li><li>[x] <strong>P3-T3</strong> (M) Filter row UI: per-type operators and value editors</li><li>[x] <strong>P3-T4</strong> (M) Column state: show/hide/pin/reorder/resize, persisted per table</li><li>[x] <strong>P3-T5</strong> (L) Cell editors: text · exact-decimal · tri-state bool · date/time+tz · enum · JSON · array chips · bytea · FK picker</li><li>[x] <strong>P3-T6</strong> (L) Staged-edit store, dirty highlighting, DML preview diff, single-transaction apply, rollback, affected-row verification [04 §6]</li><li>[x] <strong>P3-T7</strong> (M) Insert / duplicate / delete row</li><li>[x] <strong>P3-T8</strong> (M) Updatability detection from <code>tableOid</code>+<code>columnAttr</code> × <code>pg_index</code>; <code>ctid</code> opt-in; disabled-reason UI</li><li>[x] <strong>P3-T9</strong> (L) Structure panel tabs: Columns · Indexes · Constraints · Triggers · Policies · Partitions · Statistics</li><li>[x] <strong>P3-T10</strong> (L) <code>generateDdl</code> for table/view/matview/function/type/sequence; round-trip test vs <code>pg_dump</code></li><li>[x] <strong>P3-T11</strong> (M) Cell detail pane (long text / JSON tree / image / hex)</li><li>[x] <strong>P3-T12</strong> (M) Integration tests: edit-apply-verify against real PG, incl. rollback path</li></ul><h2 id="phase-4-—-sql-intelligence" tabindex="-1">Phase 4 — SQL intelligence <a class="header-anchor" href="#phase-4-—-sql-intelligence" aria-label="Permalink to &quot;Phase 4 — SQL intelligence&quot;">​</a></h2><ul><li>[x] <strong>P4-T1</strong> (L) <code>@pgsql/parser</code> WASM integration + parse cache (the maintained WASM build of libpg-query; ADR-026)</li><li>[x] <strong>P4-T2</strong> (M) Replace heuristic analyzer with AST-based classification (destructive detection, statement kind, referenced objects)</li><li>[x] <strong>P4-T3</strong> (L) Completion provider: alias-aware columns, FROM-scope, functions w/ signatures, enum values, keyword ranking</li><li>[x] <strong>P4-T4</strong> (M) Hover provider: type, default, nullability, comment, size/row estimate</li><li>[x] <strong>P4-T5</strong> (M) Go-to-definition → DDL virtual doc; find-references across open <code>.sql</code></li><li>[x] <strong>P4-T6</strong> (M) Semantic diagnostics: syntax errors, unknown relation, unknown qualified column (type mismatch not attempted - ADR-027)</li><li>[x] <strong>P4-T7</strong> (S) Formatter + format-on-save + snippets + user templates</li><li>[x] <strong>P4-T8</strong> (S) Completion latency benchmark: p95 1.1 ms on a 2 000-relation / 40 000-column fixture, budget 50 ms</li></ul><h2 id="phase-5-—-productivity-→-m2-beta" tabindex="-1">Phase 5 — Productivity → <strong>M2 beta</strong> <a class="header-anchor" href="#phase-5-—-productivity-→-m2-beta" aria-label="Permalink to &quot;Phase 5 — Productivity  → **M2 beta**&quot;">​</a></h2><blockquote><p>P5-T3 landed early: streaming CSV/JSON/JSONL export from the results panel, written through a generator into a write stream. Not started: history, saved queries, CSV import, notebooks.</p></blockquote><ul><li>[x] <strong>P5-T1</strong> (M) Query history store (JSONL, rotation) + search UI + re-run + prod exclusion</li><li>[x] <strong>P5-T2</strong> (M) Saved queries tree over a workspace folder; parameter prompts → bind params</li><li>[x] <strong>P5-T3</strong> (L) Streaming exporters: CSV · JSON · JSONL · XLSX · SQL inserts, with progress + cancel</li><li>[x] <strong>P5-T4</strong> (L) CSV import: column mapping, type-coercion preview, <code>COPY</code> fast path, error report</li><li>[x] <strong>P5-T5</strong> (L) SQL Notebooks: serializer, controller, per-<em>notebook</em> connection (ADR-029), HTML/JSON/markdown outputs, export to <code>.sql</code></li><li>[x] <strong>P5-T6</strong> (M) Onboarding walkthrough + README + docs skeleton</li><li>[x] <strong>P5-T7</strong> (S) Pre-release publish pipeline → Marketplace + Open VSX</li></ul><h2 id="phase-6-—-postgres-power" tabindex="-1">Phase 6 — Postgres power <a class="header-anchor" href="#phase-6-—-postgres-power" aria-label="Permalink to &quot;Phase 6 — Postgres power&quot;">​</a></h2><blockquote><p>Plan visualizer, red-flag rules, plan diff, session monitor with blocking chains, and the health advisor are done. The lock inspector (P6-T5) is folded into the session monitor: <code>pg_blocking_pids</code> answers the question a separate <code>pg_locks</code> view would, without a second panel. Remaining: LISTEN/NOTIFY panel, extensions and roles browser, publications/subscriptions, pgvector and PostGIS cell renderers.</p></blockquote><ul><li>[x] <strong>P6-T1</strong> (L) EXPLAIN JSON → <code>PlanNode</code> model + interactive tree visualizer</li><li>[x] <strong>P6-T2</strong> (M) Plan red-flag rules (estimate skew, seq scan on large table, external sort, lossy bitmap, nested-loop blowup)</li><li>[x] <strong>P6-T3</strong> (M) Plan diff between two runs</li><li>[x] <strong>P6-T4</strong> (M) Session monitor: <code>pg_stat_activity</code> live, blocking chain, cancel/terminate (guarded)</li><li>[x] <strong>P6-T5</strong> (S) Lock inspector over <code>pg_locks</code></li><li>[x] <strong>P6-T6</strong> (M) LISTEN/NOTIFY subscriber panel</li><li>[x] <strong>P6-T7</strong> (L) Health advisor queries + report UI + suggested DDL</li><li>[x] <strong>P6-T8</strong> (M) Extensions panel; roles/privileges browser</li><li>[x] <strong>P6-T9</strong> (S) Publications / subscriptions / replication slots listing</li><li>[x] <strong>P6-T10</strong> (M) pgvector + PostGIS cell renderers and snippets</li></ul><h2 id="phase-7-—-erd-schema-tooling" tabindex="-1">Phase 7 — ERD + schema tooling <a class="header-anchor" href="#phase-7-—-erd-schema-tooling" aria-label="Permalink to &quot;Phase 7 — ERD + schema tooling&quot;">​</a></h2><blockquote><p><strong>Complete.</strong> The generated migration opens as an ordinary SQL document and is applied through query mode, which already carries the guards (ADR-019), so there is no separate review panel or apply path.</p></blockquote><ul><li>[x] <strong>P7-T1</strong> (L) ERD canvas: dagre layout, FK edges, pan/zoom, drag, persist</li><li>[x] <strong>P7-T2</strong> (M) Neighbor filter, search, click-through to Structure</li><li>[x] <strong>P7-T3</strong> (M) PNG / SVG export</li><li>[x] <strong>P7-T4</strong> (L) Schema snapshot model + differ</li><li>[x] <strong>P7-T5</strong> (L) Migration SQL generation + review UI + apply flow (guarded)</li><li>[x] <strong>P7-T6</strong> (M) Migration file export (plain SQL / Flyway naming)</li></ul><h2 id="phase-8-—-performance-v1-0-gate" tabindex="-1">Phase 8 — Performance (<strong>v1.0 gate</strong>) <a class="header-anchor" href="#phase-8-—-performance-v1-0-gate" aria-label="Permalink to &quot;Phase 8 — Performance (**v1.0 gate**)&quot;">​</a></h2><ul><li>[~] <strong>P8-T1</strong> (L) <s>Forked <code>QueryHost</code> child process</s> — <strong>not needed</strong>, see ADR-023. Streaming 1M rows peaks at +10MB.</li><li>[~] <strong>P8-T2</strong> (M) <s>Columnar store</s> — <strong>not needed</strong>, see ADR-023. Encoding runs at 48M cells/s and the panel holds one page.</li><li>[x] <strong>P8-T3</strong> (M) End-to-end cursor streaming + webview backpressure</li><li>[x] <strong>P8-T4</strong> (M) Benchmark suite in CI with hard budgets (Roadmap P8)</li><li>[x] <strong>P8-T5</strong> (M) Memory-leak soak test (200 panels, 1 000 queries, flat heap assertion)</li><li>[x] <strong>P8-T6</strong> (S) Cold-start audit: lazy activation, deferred driver import, activation &lt; 200 ms</li></ul><h2 id="phase-9-—-second-driver" tabindex="-1">Phase 9 — Second driver <a class="header-anchor" href="#phase-9-—-second-driver" aria-label="Permalink to &quot;Phase 9 — Second driver&quot;">​</a></h2><blockquote><p><strong>Complete, with one finding.</strong> The SQLite <em>driver</em> needed no core change. The capability audit did find three places where the host had leaked Postgres assumptions - row estimation, an exact-count cast, and the blank connection form&#39;s defaults - and fixing the first required one addition to the driver contract. See ADR-021.</p></blockquote><ul><li>[x] <strong>P9-T1</strong> (M) Driver conformance kit in <code>core/test</code></li><li>[x] <strong>P9-T2</strong> (L) <code>driver-sqlite</code> full implementation</li><li>[x] <strong>P9-T3</strong> (S) Capability-gating audit: every PG-only affordance hidden, not broken</li><li>[x] <strong>P9-T4</strong> (S) CI assertion — the driver PR&#39;s diff touches no core file</li></ul><h2 id="phase-10-—-release" tabindex="-1">Phase 10 — Release <a class="header-anchor" href="#phase-10-—-release" aria-label="Permalink to &quot;Phase 10 — Release&quot;">​</a></h2><blockquote><p><strong>Everything that is code is done. What is left needs an account.</strong> The listing, the docs site and the community files landed; the publish itself needs a publisher on both marketplaces and two tokens, which is a decision rather than a task. <code>docs/13-RELEASE.md</code> is the runbook.</p></blockquote><ul><li>[x] <strong>P10-T1</strong> (M) Marketplace + Open VSX listing: categories and keywords tuned to what the Marketplace actually ranks, <code>pricing</code>, <code>qna</code> pointed at Discussions rather than the Q&amp;A tab nobody watches, and <code>capabilities</code> declaring both untrusted-workspace and virtual-workspace support honestly — the guard settings are listed as <code>restrictedConfigurations</code>, so <strong>VS Code itself</strong> ignores a workspace value for them in a workspace you have not trusted and a cloned repository cannot turn the confirmations off. The demo clips are specified rather than recorded (<code>docs/13-RELEASE.md</code> section 4) and their <code>&lt;img&gt;</code> block sits commented in the extension README: they are committed for the listing and excluded from the VSIX, because <code>vsce</code> rewrites relative links to raw GitHub URLs and a set of GIFs would otherwise be most of the download</li><li>[x] <strong>P10-T2</strong> (L) VitePress docs site under <code>docs/</code>, published to Pages by <code>.github/workflows/docs.yml</code>. Eight guide pages, ten connection recipes, the driver-authoring guide and the conformance-kit page, with the numbered design record kept as its own nav section rather than rewritten. The build fails on a dead internal link, so it is also the link check. The Remote-SSH/WSL/devcontainer caveat gets its own page and a translation table, because &quot;<code>localhost</code> means the remote&quot; is the single most common confusion (ADR-003)</li><li>[ ] <strong>P10-T3</strong> (S) Telemetry opt-in flow + documented event list [S7] — <strong>open, and it is a decision, not a task.</strong> The setting exists, defaults to false, and has no implementation and no transport behind it. Either build one or drop the setting; a setting promising collection that never happens is the one option that is wrong</li><li>[x] <strong>P10-T4</strong> (S) <code>CONTRIBUTING.md</code>, <code>SECURITY.md</code>, four issue templates plus a chooser routing vulnerabilities to private reporting, and a PR template whose checklist is the contract: capability gating, ADR-004 exactness, S1 secrets, S3 binding, and the <code>contract-change</code> label. MIT license was already in place</li><li>[ ] <strong>P10-T5</strong> (M) semantic-release, signed VSIX — <strong>partly done.</strong> <code>release.yml</code> already verifies, packages, asserts the VSIX contents, gates publishing behind a reviewed environment, publishes to both marketplaces and cuts a GitHub release, and the changelog and the odd-minor pre-release channel are in place. What is missing is semantic-release itself (the version is bumped by hand, and the tag/manifest check catches the mistake that makes) and a signing certificate</li></ul><h2 id="phase-11-—-multi-model-contract-generalization" tabindex="-1">Phase 11 — Multi-model contract generalization <a class="header-anchor" href="#phase-11-—-multi-model-contract-generalization" aria-label="Permalink to &quot;Phase 11 — Multi-model contract generalization&quot;">​</a></h2><blockquote><p><strong>Complete.</strong> The first five tasks landed with Redis (T4, T10, T9/T8, T11) before the phase itself was worked; the language, the result shapes, the conformance kit, the language-generic query surfaces and the echo driver landed together afterwards; the five partials were finished last. ADR-050 records one planned change that turned out to be unnecessary, and ADR-060 one that was done differently from how it was written down.</p><p>Contract work only. Every task here is a <code>contract-change</code>-labelled PR by the rule in ADR-021, and PostgreSQL and SQLite behave identically at the end of it. Design: <code>10-ENGINE-MODEL.md</code>. Rationale: ADR-034.</p></blockquote><ul><li>[x] <strong>P11-T1</strong> (M) <code>EngineLanguage</code> on <code>DriverAdapter</code> (optional, resolved through <code>languageOf</code>, so a driver that says nothing still means SQL); <code>Statement.sql</code> → <code>Statement.text</code> across core, every driver and the panels; <code>formatCommand</code> hook; <code>splitForLanguage</code> replaces core&#39;s splitter at every call site; UI strings, pickers, progress and tooltips read the language&#39;s <code>displayName</code> [10 §2]</li><li>[x] <strong>P11-T2</strong> (M) <code>splitStatements</code> and <code>formatCommand</code> are driver methods and every shipped driver supplies both. Done differently from how the task was written, and ADR-060 says why: moving the scanner into <code>driver-pg</code> would have meant four copies of it, and would have fixed none of what was actually wrong. The scanner and the printer stay in core and take a <code>SqlDialect</code> each driver passes, which found three real bugs the move would not have — a <code>;</code> inside a MySQL backtick identifier split a statement in two, a second <code>/*</code> in a MySQL or SQL Server buffer swallowed the rest of the file, and <code>GO</code> was handed to SQL Server as if it were T-SQL while <code>[odd;name]</code> was cut down the middle. Core keeps PostgreSQL&#39;s dialect only as the floor for a <code>.sql</code> file bound to no connection. PostgreSQL is unchanged, since its dialect is what the old default was; SQLite changes in two ways that are both corrections — it has no psql backslash commands and no dollar quoting, and used to be handed both</li><li>[~] <strong>P11-T3</strong> (M) <s><code>classifyCommand</code> on the adapter</s> — <strong>not needed</strong>, see ADR-050: drivers classify through the existing <code>parseStatement</code> hook, and ADR-027&#39;s combining rule is untouched</li><li>[x] <strong>P11-T4</strong> (L) <code>NodeDefinition.fetch</code> + tree paging + <code>Load more</code> + <code>pitta.explorer.treePageSize</code> [ADR-037]</li><li>[x] <strong>P11-T5</strong> (M) Open <code>ObjectKind</code> + <code>NodeKindDescriptor</code>: the type is <code>(typeof OBJECT_KINDS)[number] | (string &amp; {})</code>, so it is a free string with the known kinds still autocompleting, and the explorer&#39;s two static tables are gone — the icon map and the folder-label map are now <code>describeNodeKind(driver, kind)</code>, layered per field so a driver overriding an icon does not silently turn the data view off, and the browsable-kind set is the descriptor&#39;s own <code>canOpenData</code> rather than a list of the engines that shipped first. A kind nobody described still draws, Title Cased with a neutral icon. The conformance kit asserts every kind a plan can emit is core&#39;s or the driver&#39;s, which is the typo check ADR-036 promised in place of the compiler&#39;s</li><li>[x] <strong>P11-T6</strong> (M) <code>ResultShape</code> on <code>QueryHandle</code> and in <code>DriverCapabilities.resultShapes</code>, carried through the protocol into both panels; a status reply renders as a sentence and a single value as a value, and a <code>documents</code> result says its columns were sampled [ADR-038]</li><li>[x] <strong>P11-T7</strong> (L) Document projection: sampled column union, <code>inferred</code> fields, stable ordering, one level of dotted flattening</li><li>[x] <strong>P11-T8</strong> (L) Missing-vs-null, both directions. Reading was already done: the <code>MISSING</code> value in core, the <code>{missing:true}</code> wire cell, a grid token styled apart from NULL, filter-by-value offering exists/does-not-exist, and copy/export stating that they cannot carry the difference. Writing is now built — Remove field in the cell detail pane, where the field is named, rather than in a cell editor where clearing already lives. It stages the missing token, crosses the wire as one, reaches the driver as core&#39;s <code>MISSING</code> in <code>RowEdit.set</code>, and becomes <code>$unset</code> on MongoDB. Removing a field that is already absent is not an edit, and the host refuses the whole thing on an engine that declared <code>distinguishesMissing: false</code> rather than writing NULL and calling it the same thing</li><li>[x] <strong>P11-T9</strong> (M) Cursor page mode, end to end: <code>QueryHandle.nextCursor()</code>, a host fetch path that reads it off the handle rather than through <code>queryAll</code> — the offset path is untouched — and a page control that degrades to Next/Previous when the engine has no offsets. In that mode the grid drops the jump to the first page, numbers rows within the page rather than against a total it does not have, and hides the exact count, which the host refuses outright rather than answering with a full scan; Previous works by remembering the cursors already handed out. Two things the offset path does that this one must not: asking for one row more than the page holds, which a cursor cannot give back, and reporting &quot;more&quot; from a row count rather than from the cursor. Redis keeps its offsets and its visible <code>SKIP</code> (ADR-049); the echo driver exercises the cursor path, and the conformance kit now asserts it for any engine without offsets</li><li>[x] <strong>P11-T10</strong> (M) Capability additions + session overlay, resolved for the UI. <code>ConnectionManager.capabilitiesFor(profileId, database?)</code> overlays an already-open session and never connects — a question about what a connection can do must not be the thing that dials a production database — and every gate reads it: the server-activity command, the notification panel, and the data view&#39;s row-id fallback, document shape, atomicity promise and page mode. No call site reads <code>driver.capabilities</code> to decide what to show any more. Before a session exists the answer is the engine&#39;s flags, which is the honest answer to &quot;what could this connection do&quot;</li><li>[x] <strong>P11-T11</strong> (M) Non-atomic apply path: dialog wording, per-edit applied/not-applied report, degraded S4.5 verification [ADR-041]</li><li>[x] <strong>P11-T12</strong> (L) Conformance kit → <code>EngineFixture</code>: the kit issues no statement of its own, builds everything through the adapter, and walks either introspection form. PG and SQLite re-pass through <code>sqlEngineFixture</code>. Four new assertions: stable column union, missing-is-not-null, unknown-refused-on-prod, and which edits a failed non-atomic batch applied [10 §13]</li><li>[x] <strong>P11-T13</strong> (M) Query mode, saved queries, history and notebooks are language-generic: directives and cell markers read any of the three comment styles, documents are matched against every registered engine&#39;s language rather than against <code>.sql</code>, history records the language it was written in and reopens in it, saved queries list every engine&#39;s extension, and the manifest&#39;s when-clauses and activation events cover them</li><li>[x] <strong>P11-T14</strong> (S) Echo driver in <code>test/echo-driver</code>, run through the conformance kit in <code>test/unit/echoDriver.test.ts</code>: a newline-split non-SQL language, imperative paged introspection, all five result shapes, missing-not-null, cursor-only paging, a session that narrows capabilities, an unclassifiable command, and one edit that is two statements. Not shipped, not registered — this is the phase&#39;s exit test</li><li>[x] <strong>P11-T15</strong> (S) Benchmark re-run, 28/28 green and measured against a build of the same tree without this work: first page of 1M 48 ms (was 48), stream 1M x 20 3.15 s at +0.7 MB (was 3.13 s), cell encoding 24M cells/s (was 24M), activation 91 ms (was 92, budget 200). No regression. Cold activation has drifted from ADR-023&#39;s number as three drivers were added since, which the baseline run shows is not Phase 11&#39;s doing</li></ul><h2 id="phase-12-—-mongodb-driver" tabindex="-1">Phase 12 — MongoDB driver <a class="header-anchor" href="#phase-12-—-mongodb-driver" aria-label="Permalink to &quot;Phase 12 — MongoDB driver&quot;">​</a></h2><blockquote><p><strong>Complete.</strong> The driver, the editor language, completion, hover, diagnostics, tree paging, the server level, <code>readSymbols</code>, the sharding section, the red-flag rules, document import and Extended JSON export. The integration, conformance and security suites are green against MongoDB 7 standalone and a replica set; the security matrix needs no server and runs on every commit.</p><p>Detail: <code>11-ENGINE-MONGODB.md</code>. Depends on all of Phase 11.</p></blockquote><ul><li>[x] <strong>P12-T1</strong> (L) <code>packages/driver-mongodb</code> skeleton, capabilities, <code>connectionSchema</code>, URI parser, topology probe → session capabilities</li><li>[x] <strong>P12-T2</strong> (L) Connect: standalone / replica set / sharded / SRV, TLS, SCRAM · x509 · AWS IAM, pool, timeouts. SSH through <code>@pitta/ssh</code>, with <code>directConnection</code> set so a tunnelled member is not left behind by topology discovery; SRV and seed lists are refused rather than half-tunnelled</li><li>[x] <strong>P12-T3</strong> (M) <code>IntrospectionPlan</code>: databases, collections, views, indexes, estimated counts, a <code>serverNode</code> level listing shards or replica-set members, and paging on the database and collection levels</li><li>[x] <strong>P12-T4</strong> (L) Shell-dialect parser: acorn → allowlisted call shapes → BSON, constructor literals, diagnostics. <strong>No eval</strong> [ADR-042]</li><li>[x] <strong>P12-T5</strong> (M) Session + <code>QueryHandle</code> over cursors: batching, streaming, <code>fetch</code>, <code>maxTimeMS</code>. <code>nextCursor</code> arrived with P11-T9 and this driver does not implement it, which is the right answer rather than a gap: a MongoDB cursor is a server-side handle for streaming one result, not a token a later request resumes from, and the grid pages this engine with the skip and limit <code>buildSelect</code> actually writes. <code>supportsCursorPaging</code> was claiming otherwise and is now false — the flag has to describe the code</li><li>[x] <strong>P12-T6</strong> (M) Cancel: operation comments + <code>$currentOp</code> lookup + <code>killOp</code> [ADR-043]</li><li>[x] <strong>P12-T7</strong> (M) BSON type table: Decimal128 → decimal string, Int64 → bigint, ObjectId, Date, Binary, Regex, Min/MaxKey [ADR-004]</li><li>[x] <strong>P12-T8</strong> (L) <code>buildSelect</code> / <code>buildEdits</code>: filters and sorts → find, <code>$set</code>/<code>$unset</code>, nested paths, transactional apply where the topology allows, and positional array paths — an index writes to that element, <code>$[]</code> to every one, and the two operators that mean &quot;whichever matched&quot; are refused because an edit addressed by <code>_id</code> matched none</li><li>[x] <strong>P12-T9</strong> (M) Schema sampling behind the tree&#39;s columns and the Fields section, types with percentages, presence, labelled sample, and <code>readSymbols</code> for completion — bounded to a small sample per collection because it sits on a keystroke path [ADR-045]</li><li>[x] <strong>P12-T10</strong> (M) <code>readStructure</code>: fields, indexes, validation, statistics, and sharding — shard key, balancing, and how the chunks are spread, which is the only place a collection sharded onto one shard is visible</li><li>[x] <strong>P12-T11</strong> (M) <code>explain</code> → <code>QueryPlan</code> with examined-versus-returned carried onto each node, plus the Mongo red-flag rules: collection scan, examined-versus-returned, blocking sort, spill to disk, multikey index, unindexed <code>$lookup</code>. Engine facts ride on <code>PlanNode.engine</code> and reach the panel through <code>DriverAdapter.planFlags</code> [ADR-024]</li><li>[x] <strong>P12-T12</strong> (M) <code>readActivity</code> / <code>stopBackend</code> from <code>$currentOp</code> + <code>killOp</code>; <code>readHealth</code> from <code>$indexStats</code>, <code>serverStatus</code>, index shapes</li><li>[x] <strong>P12-T13</strong> (M) Completion / hover / diagnostics for the shell dialect from the sampled schema, through a new <code>EngineLanguageService</code> on the adapter: collections after <code>db.</code>, operations after a collection, sampled fields inside a filter, query operators and pipeline stages after <code>$</code>. Every suggestion and hover says the fields came from a sample</li><li>[x] <strong>P12-T14</strong> (M) <code>bulkLoad</code> through batched unordered <code>insertMany</code>, plus <code>importRecords</code> for JSON arrays and NDJSON (the format is read off the file, and one bad line costs one record) and <code>exportRecords</code> writing Extended JSON so an ObjectId survives the round trip</li><li>[x] <strong>P12-T15</strong> (M) Guards: empty-filter <code>deleteMany</code>/<code>updateMany</code>, <code>drop*</code>, <code>$out</code>/<code>$merge</code> pipeline walk, server-side JS flagged [11 §11]</li><li>[x] <strong>P12-T16</strong> (S) <code>generateDdl</code> → runnable <code>createCollection</code> + <code>createIndexes</code> script</li><li>[x] <strong>P12-T17</strong> (M) docker-compose MongoDB 7 and an 8 replica set, <code>mongo-seed.js</code> mounted into both — documents that disagree with each other on purpose — and the conformance <code>EngineFixture</code>, which is the first time the kit runs against a schemaless engine on a real server. The replica set is on mongo:7 rather than mongo:8, which refuses to start on Linux 6.19+ (SERVER-121912)</li><li>[x] <strong>P12-T18</strong> (M) Integration + security suites, green against MongoDB 7 standalone and a replica set: edit-verify by reading the document back through a second command, cancel through <code>$currentOp</code>/<code>killOp</code>, projection and missing-vs-null against real documents, and a prod guard matrix that runs on every commit. Running them found five real bugs, all fixed - an unreadable command classified safe rather than failing closed, an empty-filter <code>deleteMany</code> that was not destructive, a cursor error escaping as a raw <code>MongoServerError</code>, an explicit null dropped on insert, an <code>_id</code> always coerced to ObjectId (so a numeric or string key never matched), cancel released before the cursor was pulled (so it killed nothing), and writes inside a transaction issued without the client session (so nothing rolled back)</li></ul><h2 id="phase-13-—-redis-driver" tabindex="-1">Phase 13 — Redis driver <a class="header-anchor" href="#phase-13-—-redis-driver" aria-label="Permalink to &quot;Phase 13 — Redis driver&quot;">​</a></h2><blockquote><p><strong>Complete.</strong> The driver, the <code>.redis</code> editor language, the subscription panel, the TTL action, cluster&#39;s node level, cross-slot handling, replica reads, the big-key and TTL-coverage findings, and the settings that relax <code>KEYS</code>/<code>MONITOR</code>. Green against Redis 6.2, 7, redis-stack and a one-node cluster. The 1M-key assertion is opt-in behind <code>PITTA_TEST_REDIS_BIG=1</code>, because writing a million keys takes a minute and nobody wants that on every run - it passes. ADR-049 records how offset paging over a scan is expressed.</p><p>Detail: <code>12-ENGINE-REDIS.md</code>.</p></blockquote><ul><li>[x] <strong>P13-T1</strong> (L) <code>packages/driver-redis</code> skeleton, capabilities, <code>connectionSchema</code> (standalone / sentinel / cluster), <code>redis(s)://</code> parser</li><li>[x] <strong>P13-T2</strong> (M) Connect: ACL auth, TLS, <code>CLIENT SETNAME</code>, <code>COMMAND INFO</code> table, topology probe, and SSH through <code>@pitta/ssh</code> — standalone only, because cluster and sentinel are handed the other nodes&#39; own addresses and one forward cannot serve them</li><li>[x] <strong>P13-T3</strong> (L) Keyspace tree: databases via <code>DBSIZE</code> / <code>INFO keyspace</code> (CONFIG-disabled fallback), SCAN prefix folders from a bounded sample, cursor paging, estimate labelling [ADR-044]</li><li>[x] <strong>P13-T4</strong> (L) Per-type value views + <code>buildSelect</code>: string · hash · list · set · zset · stream · JSON module</li><li>[~] <strong>P13-T5</strong> (M) <code>buildEdits</code> per type and the no-rollback wording — done, including the preview and the partial-apply report; commands run in order without <code>MULTI</code>/<code>EXEC</code>, which changes nothing about what is promised</li><li>[x] <strong>P13-T6</strong> (M) TTL — shown in the structure view, and the editor action is wired: a prompt on the key rather than a cell in the grid, because TTL is a property of the key and not one of its fields. Empty clears it through <code>PERSIST</code>, which is not the same as an expiry of zero</li><li>[x] <strong>P13-T7</strong> (M) <code>.redis</code> language: a splitter that ends a command at a newline <em>outside</em> quotes, completion and hover built from the server&#39;s own <code>COMMAND DOCS</code>, subcommands of the container commands, and diagnostics for unbalanced quotes, refused commands and commands this server does not have. Keys are deliberately never suggested (ADR-044)</li><li>[x] <strong>P13-T8</strong> (M) Guards from command flags; always-destructive list; <code>KEYS</code> and <code>MONITOR</code> refusals; <code>EVAL</code> handling; unknown fails closed on prod [12 §9]</li><li>[x] <strong>P13-T9</strong> (M) The notify panel is now the subscription panel and knows no engine: discovery is <code>readChannels</code>, publishing is <code>buildPublish</code>, delivery is <code>session.listen</code>. Redis offers <code>PUBSUB CHANNELS</code> plus the keyspace-notification patterns, and only when <code>notify-keyspace-events</code> is actually set. <code>MONITOR</code> is opt-in through <code>pitta.redis.allowMonitor</code>, stops itself after <code>pitta.redis.monitorSeconds</code>, and is refused on production whatever the setting says</li><li>[x] <strong>P13-T10</strong> (M) <code>readActivity</code> / <code>stopBackend</code> from <code>CLIENT LIST</code> / <code>CLIENT KILL</code></li><li>[x] <strong>P13-T11</strong> (M) <code>readHealth</code>: memory, eviction, persistence, replication, blocked clients, hit rate, slowlog, and a bounded keyspace sample reporting the largest key and how much of the sample expires — a sample, and labelled as one, because the alternative is <code>KEYS</code> (ADR-044)</li><li>[x] <strong>P13-T12</strong> (S) Cluster mode: a nodes level reading <code>CLUSTER NODES</code> with slot ranges (and <code>INFO replication</code> off a cluster), cross-slot commands split per slot and merged back in the caller&#39;s key order where that is meaningful and refused with the hash-tag explanation where it is not, and opt-in replica reads — opt-in because a replica can be behind, and a client that quietly read from one makes staleness look like a bug in the data</li><li>[x] <strong>P13-T13</strong> (M) docker-compose Redis 6.2 and 7 plus an integration suite that seeds and cleans up after itself; redis-stack and a one-node cluster added, and the conformance <code>EngineFixture</code> written against a hash. Green against 6.2, 7, redis-stack and the cluster</li><li>[x] <strong>P13-T14</strong> (M) Safety tests: <code>KEYS</code> and <code>MONITOR</code> refusals, the read-only guard, unknown-fails-closed, and value binding against a scripted server and again against a real one, plus the partial-apply promise, the TTL round trip, and the cluster&#39;s slot arithmetic checked against <code>CLUSTER KEYSLOT</code>. The 1M-key assertion runs under <code>PITTA_TEST_REDIS_BIG=1</code> and passes: a million keys written, a prefix folder still expanding in well under the budget. Running the suite found two real bugs - the whole file had never executed (its reachability flag was read at collection time, so every test silently skipped), and <code>COMMAND INFO</code> with no arguments is empty on Redis 6.2, which left the oldest supported server with no classification table and every write past the read-only guard</li></ul><h2 id="phase-14-—-mysql-mariadb-driver" tabindex="-1">Phase 14 — MySQL / MariaDB driver <a class="header-anchor" href="#phase-14-—-mysql-mariadb-driver" aria-label="Permalink to &quot;Phase 14 — MySQL / MariaDB driver&quot;">​</a></h2><blockquote><p><strong>Complete.</strong> Written alongside MongoDB rather than after it, and it did land against the existing contract almost unchanged - which is the result ADR-047 predicted and the reason it was scheduled last. Results stream, the plan has MySQL&#39;s own red flags, and the tunnel is shared with every other driver. The conformance and integration suites are green against MySQL 8 and MariaDB 11 - which is what &quot;supported&quot; means (docs/03-DRIVER-API.md section 6).</p></blockquote><ul><li>[x] <strong>P14-T1</strong> (L) <code>packages/driver-mysql</code> on <code>mysql2</code>: connect, TLS, pool, <code>KILL QUERY</code> cancel, and SSH through <code>@pitta/ssh</code></li><li>[x] <strong>P14-T2</strong> (L) <code>information_schema</code> introspection; backtick quoting; <code>?</code> placeholders; DECIMAL/BIGINT exact</li><li>[x] <strong>P14-T3</strong> (M) <code>EXPLAIN FORMAT=JSON</code> → plan model, with <code>EXPLAIN ANALYZE</code> supplying measured time, plus the MySQL red-flag rules: a full scan, an available index the optimizer passed over, examined-versus-returned, a low <code>filtered</code> percentage, a filesort, a temporary table</li><li>[x] <strong>P14-T4</strong> (M) Processlist monitor; <code>performance_schema</code> and status-counter health report; <code>SHOW CREATE</code> DDL</li><li>[~] <strong>P14-T5</strong> (M) Bulk import through batched INSERTs in one transaction. <code>LOAD DATA LOCAL INFILE</code> is deliberately not used — see ADR-056</li><li>[x] <strong>P14-T6</strong> (M) docker-compose MySQL 8 + MariaDB 11, with the conformance and integration suites green against both (<code>PITTA_TEST_MYSQL_FLAVOUR=mariadb</code> picks the second). Running them found two real bugs: <code>EXPLAIN ANALYZE</code> is a syntax error on MariaDB, which spells it <code>ANALYZE FORMAT=JSON</code>, and MariaDB&#39;s plan JSON names its row counts <code>rows</code>/<code>r_rows</code> rather than <code>rows_examined_per_scan</code> - so every MariaDB plan reached the red-flag rules with no numbers in it and reported nothing at all</li><li>[x] <strong>P14-T8</strong> (M) Streaming results: a query asked to stream holds its own pooled connection, leaves the stream paused and reads only what <code>fetch</code> pulls, and a connection abandoned mid-result is destroyed rather than handed back half-read. <code>supportsCursors</code> is now true because the behaviour is</li><li>[x] <strong>P14-T7</strong> (S) The guide exists (P10-T2) and answers every gap the fourth, fifth and sixth drivers found; <code>03-DRIVER-API.md</code> section 7 is now the index that says which section answers which, rather than a list of things nobody had written down. Finishing Phase 11 against six written drivers added four more, all of them now sections of the guide: whose SQL a dialect is (ADR-060), naming a tree level core has no vocabulary for, reporting the end of a scan with <code>nextCursor</code>, and that removing a field is not clearing it</li></ul><h2 id="phase-15-—-sql-server-driver" tabindex="-1">Phase 15 — SQL Server driver <a class="header-anchor" href="#phase-15-—-sql-server-driver" aria-label="Permalink to &quot;Phase 15 — SQL Server driver&quot;">​</a></h2><blockquote><p><strong>Complete.</strong> Relational and SQL, so most of it landed against the existing contract unchanged - and the parts that did not were about TDS rather than about T-SQL. Every statement goes through <code>sp_executesql</code>, which makes <code>USE</code> and session <code>SET</code> meaningless (ADR-059), and the protocol decodes <code>decimal</code> into a double, which is the only engine so far where ADR-004 had to be defended on the server (ADR-058). The conformance and integration suites are green against SQL Server 2022 - which is what &quot;supported&quot; means (docs/03-DRIVER-API.md section 6).</p></blockquote><ul><li>[x] <strong>P15-T1</strong> (L) <code>packages/driver-mssql</code> on <code>mssql</code>/<code>tedious</code>: connect, TLS mapped onto <code>encrypt</code> + <code>trustServerCertificate</code>, pool, NTLM for a domain login, named instances, attention-packet cancel, and SSH through <code>@pitta/ssh</code></li><li>[x] <strong>P15-T2</strong> (L) <code>sys</code> catalog introspection with three-part names so the tree crosses databases without <code>USE</code>; bracket quoting; <code>@1</code> placeholders; <code>decimal</code>/<code>bigint</code> exact (ADR-058)</li><li>[x] <strong>P15-T3</strong> (M) <code>SHOWPLAN_ALL</code> and <code>STATISTICS PROFILE</code> → plan model through a pinned batch (ADR-059), plus the SQL Server red-flag rules: a scan judged against the table&#39;s own row count rather than what it returned, a key lookup that ran too often, an estimate far from the actual, a <code>CONVERT_IMPLICIT</code> that quietly disables an index, and the server&#39;s own operator warnings</li><li>[x] <strong>P15-T4</strong> (M) <code>sys.dm_exec_*</code> session monitor with the blocker named directly; DMV health report (missing indexes, unread indexes, page life expectancy, log space); <code>sys.sql_modules</code> DDL for modules and a composed <code>CREATE TABLE</code> for tables</li><li>[x] <strong>P15-T5</strong> (M) Streaming results: a query asked to stream pauses the request as soon as a page has arrived and resumes only when <code>fetch</code> asks, and a request abandoned mid-result is cancelled rather than returned to the pool half-read</li><li>[x] <strong>P15-T7</strong> (M) Security and correctness review of the finished driver, which found five things worth the pass. A failed <code>explain</code> left <code>SET SHOWPLAN_ALL ON</code> on its pooled connection - the setting outlives both the statement and the rollback - so every later query that borrowed that connection returned <em>no rows at all</em> rather than an error; the cleanup now runs whatever happened, with a regression test that runs more queries than the pool has connections. <code>readOnly</code> was enforced nowhere in the driver while the capability claimed the server was doing it (S4.10); it is now refused in the client, the flag says false, and the T-SQL writes the shared heuristic reads as harmless - <code>EXEC</code>, <code>SELECT … INTO</code>, <code>BULK INSERT</code>, <code>RESTORE</code>, <code>BACKUP</code>, <code>DBCC</code>, <code>KILL</code> - are classified by the driver so the read-only block and the production confirmation see them (ADR-007, S4.4). A case-sensitive <code>LIKE</code> put a <code>COLLATE</code> clause on whatever column it was given, which is a syntax error on an int or a datetime. A <code>time</code> column read back as <code>1970-01-01T03:04:05Z</code>, an epoch date in a cell that holds a time of day, and a <code>date</code> as a midnight instant a time zone could move. And the health report&#39;s suggested SQL did not quote the identifiers it had read out of the catalog</li><li>[x] <strong>P15-T6</strong> (M) docker-compose SQL Server 2022, with the conformance and integration suites green against it. Running them found three real bugs: <code>batch()</code> reports no column metadata at all (only <code>query()</code> does), so every plan rowset arrived unreadable; <code>mssql</code>&#39;s type objects are functions that <em>carry</em> a <code>declaration</code> rather than returning one, so every decimal column was described as an nvarchar and skipped its scale; and a plan&#39;s scan node reports the rows it produced rather than the rows it read, so a full scan of twenty thousand rows returning three was not reported at all until the driver started asking the catalog for the table&#39;s real size</li></ul><h2 id="phase-16-—-stored-routines" tabindex="-1">Phase 16 — Stored routines <a class="header-anchor" href="#phase-16-—-stored-routines" aria-label="Permalink to &quot;Phase 16 — Stored routines&quot;">​</a></h2><blockquote><p>A procedure was something Pitta could <em>show</em>. Everything people actually do with one - change it, call it, watch it run, find out where it broke - was done elsewhere, which for a five-hundred-line procedure means a scratch buffer, a paste back, and <code>RAISE</code> statements added one run at a time. This phase is that loop, closed inside the editor. What it is not is a step debugger: breakpoints, stepping and variable watch are their own phase, and they belong behind a debug adapter rather than in a panel.</p></blockquote><ul><li>[x] <strong>P16-T1</strong> (M) <code>RoutineSupport</code> on the driver contract - <code>describe</code>, <code>buildReplace</code>, <code>buildDrop</code>, <code>buildInvoke</code>, <code>locateError</code> - with the data types in <code>model/routine.ts</code> so the capability can name <code>Session</code> without core importing itself in a circle. <code>PittaError</code> and the statement wire carry <code>context</code>, which is the engine&#39;s own stack</li><li>[x] <strong>P16-T2</strong> (L) Routines are edited as documents: a <code>FileSystemProvider</code> on <code>pitta-routine</code>, so a definition gets a dirty marker, <code>Ctrl+S</code>, revert and a diff against the server for free. Saving runs the guards, replaces inside a transaction where the engine has one, and puts a failure on the line of the <em>body</em> it happened in. The Postgres overload trap - <code>CREATE OR REPLACE FUNCTION</code> with a changed argument type creates a second function and reports success - is detected against the server after the save rather than by parsing the edited text</li><li>[x] <strong>P16-T3</strong> (M) Run Routine: arguments come from the catalog with their names, declared types and defaults, <code>OUT</code> parameters are not asked for, and the prompt is the parameters form from P13. The call is built by the driver - <code>CALL</code>, <code>SELECT * FROM</code>, <code>EXEC … OUTPUT</code> and the select that reads it back - and the runner gained a way to be handed statements rather than splitting text into them</li><li>[x] <strong>P16-T4</strong> (M) Messages while it runs. SQL Server&#39;s <code>PRINT</code> was never listened for and MySQL&#39;s warnings were never asked for, so on two of the three engines a long procedure reported nothing at all; both are wired now, and every notice is pushed to the panel as it arrives instead of being attached to the statement when it ends. A failure shows the engine&#39;s stack under <em>Where</em></li><li>[x] <strong>P16-T5</strong> (M) SQL Server and MySQL parity for reading, replacing and calling. MySQL is the engine with no <code>CREATE OR REPLACE</code> and no transactional DDL, so its replacement is a drop and a create that nothing undoes: the editor warns first and restores the old definition when the create fails</li><li>[ ] <strong>P16-T6</strong> (M) Integration tests against the docker compose: a routine round-trips through <code>describe → buildReplace → describe</code> unchanged, a failure inside a body lands on the right line, and <code>PRINT</code>/<code>RAISE</code>/<code>SIGNAL</code> output arrives while the call is still running</li></ul>',49)])])}const p=t(s,[["render",r]]);export{u as __pageData,p as default};
